input.args:
evaluate(() => {
  // Check for elements near the thin bar position
  const elements = [];
  for (let x = 1170; x <= 1190; x += 5) {
    const el = document.elementFromPoint(x, 820);
    if (el) {
      elements.push({
        x,
        tag: el.tagName,
        class: el.className,
        id: el.id,
        parent: el.parentElement ? el.parentElement.className : null
      });
    }
  }
  return elements;
})
